"use strict";(self["webpackChunkassignment3_3_frontend_main"]=self["webpackChunkassignment3_3_frontend_main"]||[]).push([[344],{28344:(a,e,t)=>{t.r(e),t.d(e,{default:()=>r});var i=t(56768),l={class:"container family-recipes-page"};function d(a,e,t,d,o,s){return(0,i.uX)(),(0,i.CE)("div",l,e[0]||(e[0]=[(0,i.Fv)('<h1 class="display-4 fw-bold text-primary text-center" data-v-59897005>Family Recipes</h1><p class="lead text-muted text-center mb-5" data-v-59897005>Treasured recipes passed down through generations</p><div class="recipes-container" data-v-59897005><div class="recipe-card" data-v-59897005><h2 class="recipe-title" data-v-59897005>Grandma&#39;s Apple Strudel</h2><div class="recipe-meta" data-v-59897005><p data-v-59897005><strong data-v-59897005>From:</strong> Grandmother Shoshana</p><p data-v-59897005><strong data-v-59897005>When we make it:</strong> Holiday gatherings, especially during Rosh Hashanah</p></div><div class="recipe-image" data-v-59897005><img src="https://media.gettyimages.com/id/137881018/photo/close-up-of-a-slice-of-apple-strudel-cake.jpg?s=2048x2048&amp;w=gi&amp;k=20&amp;c=imiHpZEGooEMoa2x2T0tf-OFXYNJpR46bSsxtDtwks8=" alt="Apple strudel" class="main-image" data-v-59897005></div><div class="recipe-content" data-v-59897005><div class="ingredients" data-v-59897005><h3 data-v-59897005>Ingredients:</h3><ul data-v-59897005><li data-v-59897005>6 Granny Smith apples, peeled and thinly sliced</li><li data-v-59897005>1/2 cup granulated sugar</li><li data-v-59897005>1 tablespoon ground cinnamon</li><li data-v-59897005>1/2 cup raisins</li><li data-v-59897005>1/2 cup chopped walnuts</li><li data-v-59897005>8 sheets phyllo dough</li><li data-v-59897005>1/2 cup melted butter</li><li data-v-59897005>1/4 cup breadcrumbs</li><li data-v-59897005>Powdered sugar for dusting</li></ul></div><div class="preparation" data-v-59897005><h3 data-v-59897005>Preparation:</h3><ol data-v-59897005><li data-v-59897005>Preheat oven to 350°F (175°C).</li><li data-v-59897005>In a large bowl, mix the sliced apples with sugar, cinnamon, raisins, and walnuts.</li><li data-v-59897005>Lay out one sheet of phyllo dough and brush with melted butter. Sprinkle with breadcrumbs.</li><li data-v-59897005>Layer another sheet on top and repeat until you have 4 layers.</li><li data-v-59897005>Spread half the apple mixture along one edge of the phyllo stack.</li><li data-v-59897005>Roll the phyllo dough to enclose the filling, tucking in the sides.</li><li data-v-59897005>Repeat with remaining phyllo sheets and filling to make a second strudel.</li><li data-v-59897005>Place on a baking sheet and brush with more butter.</li><li data-v-59897005>Bake for 30-35 minutes until golden brown.</li><li data-v-59897005>Cool slightly, dust with powdered sugar, and slice to serve.</li></ol></div><div class="family-story" data-v-59897005><h3 data-v-59897005>Family Story:</h3><p data-v-59897005>This recipe has been in our family for over 80 years. Grandma Shoshana learned it from her mother, who brought it from Vienna. According to family lore, this strudel once won a neighborhood baking contest in 1965!</p></div></div></div><div class="recipe-card" data-v-59897005><h2 class="recipe-title" data-v-59897005>Uncle Moshe&#39;s Brisket</h2><div class="recipe-meta" data-v-59897005><p data-v-59897005><strong data-v-59897005>From:</strong> Uncle Moshe</p><p data-v-59897005><strong data-v-59897005>When we make it:</strong> special family gatherings</p></div><div class="recipe-image" data-v-59897005><img src="https://images.unsplash.com/photo-1606491956689-2ea866880c84?ixlib=rb-1.2.1&amp;auto=format&amp;fit=crop&amp;w=1350&amp;q=80" alt="Beef Brisket" class="main-image" data-v-59897005></div><div class="recipe-content" data-v-59897005><div class="ingredients" data-v-59897005><h3 data-v-59897005>Ingredients:</h3><ul data-v-59897005><li data-v-59897005>4-5 pound beef brisket</li><li data-v-59897005>2 tablespoons olive oil</li><li data-v-59897005>3 large onions, sliced</li><li data-v-59897005>4 cloves garlic, minced</li><li data-v-59897005>2 cups beef broth</li><li data-v-59897005>1 cup red wine</li><li data-v-59897005>3 tablespoons tomato paste</li><li data-v-59897005>2 bay leaves</li><li data-v-59897005>1 tablespoon paprika</li><li data-v-59897005>1 teaspoon dried thyme</li><li data-v-59897005>Salt and pepper to taste</li><li data-v-59897005>3 large carrots, cut into chunks</li><li data-v-59897005>4 potatoes, quartered</li></ul></div><div class="preparation" data-v-59897005><h3 data-v-59897005>Preparation:</h3><ol data-v-59897005><li data-v-59897005>Preheat oven to 325°F (165°C).</li><li data-v-59897005>Season brisket generously with salt and pepper on both sides.</li><li data-v-59897005>Heat olive oil in a large Dutch oven over medium-high heat.</li><li data-v-59897005>Sear the brisket until browned on both sides, about 5 minutes per side.</li><li data-v-59897005>Remove brisket and set aside. Add onions to the pot and cook until softened.</li><li data-v-59897005>Add garlic and cook for another minute until fragrant.</li><li data-v-59897005>Stir in tomato paste, then add wine to deglaze the pot, scraping up browned bits.</li><li data-v-59897005>Add beef broth, bay leaves, paprika, and thyme. Bring to a simmer.</li><li data-v-59897005>Return brisket to the pot, cover, and transfer to the oven.</li><li data-v-59897005>Cook for 3 hours, then add carrots and potatoes around the brisket.</li><li data-v-59897005>Continue cooking for another 1-2 hours until meat is fork-tender.</li><li data-v-59897005>Let rest for 20 minutes before slicing against the grain.</li><li data-v-59897005>Serve with vegetables and sauce from the pot.</li></ol></div><div class="family-story" data-v-59897005><h3 data-v-59897005>Family Story:</h3><p data-v-59897005>Uncle Moshe&#39;s brisket recipe has been perfected over 30 years. He learned the basics from his father, but added his own touches after traveling through Eastern Europe. The recipe changed forever when he accidentally added twice the amount of wine one Passover, creating the rich sauce we all love today.</p></div></div></div><div class="recipe-card" data-v-59897005><h2 class="recipe-title" data-v-59897005>Aunt Mor&#39;s Baklava</h2><div class="recipe-meta" data-v-59897005><p data-v-59897005><strong data-v-59897005>From:</strong> Aunt Mor</p><p data-v-59897005><strong data-v-59897005>When we make it:</strong> Festive celebrations and family weddings</p></div><div class="recipe-image" data-v-59897005><img src="https://media.gettyimages.com/id/1067828156/photo/perfect-sweet-baklava-with-pistachio-on-marble-background.jpg?s=2048x2048&amp;w=gi&amp;k=20&amp;c=pxq1qvDfX95uWtr_ehXoBtc_r3u2giHFVsxEJ0cnfCQ=" alt="Baklava" class="main-image" data-v-59897005></div><div class="recipe-content" data-v-59897005><div class="ingredients" data-v-59897005><h3 data-v-59897005>Ingredients:</h3><ul data-v-59897005><li data-v-59897005>1 package (16 oz) phyllo dough, thawed</li><li data-v-59897005>1 pound mixed nuts (walnuts, pistachios, almonds), finely chopped</li><li data-v-59897005>1 teaspoon ground cinnamon</li><li data-v-59897005>1/4 teaspoon ground cloves</li><li data-v-59897005>1/4 teaspoon ground cardamom</li><li data-v-59897005>1 cup unsalted butter, melted</li><li data-v-59897005>1 cup honey</li><li data-v-59897005>1/2 cup water</li><li data-v-59897005>1 cup granulated sugar</li><li data-v-59897005>1 teaspoon vanilla extract</li><li data-v-59897005>1 teaspoon rose water (optional)</li><li data-v-59897005>1 tablespoon lemon juice</li></ul></div><div class="preparation" data-v-59897005><h3 data-v-59897005>Preparation:</h3><ol data-v-59897005><li data-v-59897005>Preheat oven to 350°F (175°C).</li><li data-v-59897005>In a large bowl, combine chopped nuts, cinnamon, cloves, and cardamom.</li><li data-v-59897005>Brush the bottom of a 9x13 inch baking dish with melted butter.</li><li data-v-59897005>Layer 6 sheets of phyllo dough, brushing each with butter.</li><li data-v-59897005>Spread 1/3 of the nut mixture over the phyllo.</li><li data-v-59897005>Layer 4 more sheets of phyllo dough, brushing each with butter.</li><li data-v-59897005>Add another 1/3 of the nut mixture.</li><li data-v-59897005>Repeat with 4 more sheets and the remaining nut mixture.</li><li data-v-59897005>Top with 6 sheets of phyllo, brushing each with butter.</li><li data-v-59897005>Cut the baklava into diamond shapes with a sharp knife.</li><li data-v-59897005>Bake for 50 minutes until golden and crisp.</li><li data-v-59897005>While baking, make the syrup: combine honey, water, sugar, vanilla, rose water, and lemon juice in a saucepan.</li><li data-v-59897005>Bring to a boil, then simmer for 20 minutes.</li><li data-v-59897005>Pour the hot syrup over the baklava immediately after it comes out of the oven.</li><li data-v-59897005>Let cool completely before serving.</li></ol></div><div class="family-story" data-v-59897005><h3 data-v-59897005>Family Story:</h3><p data-v-59897005>Aunt Mor&#39;s baklava is famous in our extended family. She learned the recipe during a trip to Istanbul in the 1980s, where she spent two weeks learning from local pastry chefs. She&#39;s been making it for every family wedding since 1988. The rose water is her secret ingredient that gives it a distinctive floral note.</p></div></div></div></div>',3)]))}const o={name:"FamilyRecipesPage"};var s=t(71241);const n=(0,s.A)(o,[["render",d],["__scopeId","data-v-59897005"]]),r=n}}]);
